package main

import (
	"encoding/json"
	"log"
	"sync"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// server holds all of the append-only logs and the offsets clients have
// committed.  A single node serves every request, so a plain mutex is enough
// to serialise access.
type server struct {
	mu sync.Mutex

	// logs maps a key to its messages.  The message at slice index i has
	// offset i, so offsets are dense and strictly increasing per key.
	logs map[string][]json.RawMessage

	// committed maps a key to the last offset a client committed for it.
	committed map[string]int64
}

func newServer() *server {
	return &server{
		logs:      make(map[string][]json.RawMessage),
		committed: make(map[string]int64),
	}
}

// sendRequest is the body of a "send" request.  The value is kept as raw JSON
// so that it is echoed back byte-for-byte, whatever its representation.
type sendRequest struct {
	Key string          `json:"key"`
	Msg json.RawMessage `json:"msg"`
	// Some clients may spell the value field "value"; accept that too.
	Value json.RawMessage `json:"value"`
}

type pollRequest struct {
	Offsets map[string]int64 `json:"offsets"`
}

type commitOffsetsRequest struct {
	Offsets map[string]int64 `json:"offsets"`
}

type listCommittedOffsetsRequest struct {
	Keys []string `json:"keys"`
}

func main() {
	n := maelstrom.NewNode()
	s := newServer()

	n.Handle("send", func(msg maelstrom.Message) error {
		var req sendRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		value := req.Msg
		if len(value) == 0 {
			value = req.Value
		}
		if len(value) == 0 {
			value = json.RawMessage("null")
		}

		s.mu.Lock()
		offsets := s.logs[req.Key]
		offset := int64(len(offsets))
		// Copy the value so we do not retain a slice that might be reused
		// by the JSON decoder.
		v := make(json.RawMessage, len(value))
		copy(v, value)
		s.logs[req.Key] = append(offsets, v)
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{
			"type":   "send_ok",
			"offset": offset,
		})
	})

	n.Handle("poll", func(msg maelstrom.Message) error {
		var req pollRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		s.mu.Lock()
		msgs := make(map[string][][2]any, len(req.Offsets))
		for key, start := range req.Offsets {
			entries := s.logs[key]
			if start < 0 {
				start = 0
			}
			if start >= int64(len(entries)) {
				// Nothing at or after this offset: omit the key.
				continue
			}
			pairs := make([][2]any, 0, len(entries)-int(start))
			for i := int(start); i < len(entries); i++ {
				pairs = append(pairs, [2]any{int64(i), entries[i]})
			}
			msgs[key] = pairs
		}
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{
			"type": "poll_ok",
			"msgs": msgs,
		})
	})

	n.Handle("commit_offsets", func(msg maelstrom.Message) error {
		var req commitOffsetsRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		s.mu.Lock()
		for key, offset := range req.Offsets {
			s.committed[key] = offset
		}
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{"type": "commit_offsets_ok"})
	})

	n.Handle("list_committed_offsets", func(msg maelstrom.Message) error {
		var req listCommittedOffsetsRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}

		s.mu.Lock()
		offsets := make(map[string]int64, len(req.Keys))
		for _, key := range req.Keys {
			if offset, ok := s.committed[key]; ok {
				offsets[key] = offset
			}
		}
		s.mu.Unlock()

		return n.Reply(msg, map[string]any{
			"type":    "list_committed_offsets_ok",
			"offsets": offsets,
		})
	})

	if err := n.Run(); err != nil {
		log.Fatal(err)
	}
}

